PROTECTED_TOP_LEVEL = {"data", "logs", "models", ".venv", "venv", ".git", ".env", "__pycache__"}
ALLOWED_ROOT = {"app.py", "README.md", "bootstrap.py", "requirements.txt", "pytest.ini", "setup.bat", "start.bat"}
ALLOWED_PREFIXES = ("src/", "scripts/", "tests/", ".streamlit/")


def is_project(path: Path) -> bool:
    return (path / "app.py").is_file() and (path / "src").is_dir() and (path / "requirements.txt").is_file()


def find_projects() -> list[Path]:
    base = Path(__file__).resolve().parent
    raw = [base, base / "company-knowledge-search", Path.cwd(), Path.cwd() / "company-knowledge-search"]
    found: list[Path] = []
    for item in raw:
        item = item.resolve()
        if is_project(item) and item not in found:
            found.append(item)
    return found


def choose_project(candidates: list[Path]) -> Path:
    if not candidates:
        raise RuntimeError("No company-knowledge-search project was found beside or containing this updater.")
    if len(candidates) == 1:
        return candidates[0]
    print("Multiple candidate projects were found:")
    for index, item in enumerate(candidates, 1):
        print(f"  {index}. {item}")
    try:
        selected = int(input("Select the project number to update: ").strip())
        return candidates[selected - 1]
    except (ValueError, IndexError):
        raise RuntimeError("No valid project selection was provided; nothing was changed.")


def read_payload() -> tuple[zipfile.ZipFile, list[str]]:
    archive = zipfile.ZipFile(BytesIO(base64.b64decode(PAYLOAD_B64.encode("ascii"))))
    names = archive.namelist()
    if not names:
        raise RuntimeError("Embedded payload is empty.")
    for name in names:
        path = Path(name)
        if path.is_absolute() or ".." in path.parts or path.parts[0] in PROTECTED_TOP_LEVEL:
            raise RuntimeError("Unsafe payload entry: " + name)
        if not (name in ALLOWED_ROOT or name.startswith(ALLOWED_PREFIXES)):
            raise RuntimeError("Unexpected payload entry: " + name)
    return archive, names


def validate_code(root: Path, names: list[str]) -> None:
    for name in names:
        path = root / name
        if not path.is_file():
            raise RuntimeError("Missing staged file: " + str(path))
        if path.suffix == ".py":
            py_compile.compile(str(path), doraise=True)
    # Lightweight imports validate the runtime graph without importing app.py,
    # which intentionally executes Streamlit setup at module import time.
    sys.path.insert(0, str(root))
    try:
        for module in ("src.database", "src.indexing", "src.hybrid_retrieval", "src.rag_pipeline", "src.llm_provider"):
            __import__(module)
    finally:
        sys.path.pop(0)
        for module in list(sys.modules):
            if module == "src" or module.startswith("src."):
                sys.modules.pop(module, None)


def dependency_report() -> list[str]:
    required = {"pymupdf": "fitz", "python-pptx": "pptx", "python-docx": "docx", "streamlit": "streamlit", "openpyxl": "openpyxl", "numpy": "numpy"}
    return [name for name, module in required.items() if importlib.util.find_spec(module) is None]


def rollback(root: Path, backup: Path, replaced: list[str], created: list[str]) -> None:
    for name in reversed(replaced):
        saved = backup / name
        if saved.exists():
            destination = root / name
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(saved, destination)
    for name in created:
        destination = root / name
        if destination.exists():
            destination.unlink()


def main() -> int:
    root = choose_project(find_projects())
    archive, names = read_payload()
    print("Detected application:\n" + str(root))
    print(f"\nFiles to update: {len(names)}")
    print("Database/documents/embeddings/models/config/logs: preserved")
    print("\nProceeding...")

    timestamp = time.strftime("%Y%m%d-%H%M%S")
    backup = root / ".upgrade_backups" / f"{VERSION}-{timestamp}"
    stage = Path(tempfile.mkdtemp(prefix="rag_hybrid_stage_", dir=str(root)))
    replaced: list[str] = []
    created: list[str] = []
    try:
        for name in names:
            staged = stage / name
            staged.parent.mkdir(parents=True, exist_ok=True)
            staged.write_bytes(archive.read(name))
        validate_code(stage, names)

        backup.mkdir(parents=True, exist_ok=False)
        for name in names:
            destination = root / name
            staged = stage / name
            if destination.exists():
                saved = backup / name
                saved.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(destination, saved)
                replaced.append(name)
            else:
                created.append(name)
            temporary = destination.with_name(destination.name + ".update-new")
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(staged, temporary)
            os.replace(temporary, destination)

        validate_code(root, names)
    except Exception as exc:
        try:
            rollback(root, backup, replaced, created)
        finally:
            shutil.rmtree(stage, ignore_errors=True)
        print("Update failed; modified application files were rolled back. " + str(exc), file=sys.stderr)
        return 1
    finally:
        archive.close()

    shutil.rmtree(stage, ignore_errors=True)
    missing = dependency_report()
    print("\nUpdate complete.")
    print("Backup: " + str(backup))
    if missing:
        print("Missing Python dependencies: " + ", ".join(missing))
        print("Install them with: py -m pip install -r requirements.txt")
    else:
        print("Python dependencies: available")
    print("Syntax/import validation: passed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

